graphql.query:
query EventById($eventId: ID!) {
  event(id: $eventId) {
    id
    slug
    title
    beginsAt
    endsAt
    htmlDescription
    isLive
    language
    timezone
    totalPlannings
    totalExhibitors
    totalSpeakers
    banner { imageUrl embeddedVideo { videoId } }
    address { place street city zipCode state country }
    groups { id name peopleCount }
  }
}

query events($eventIds: [String!]) {
  events(ids: $eventIds) {
    id
    title
    beginsAt
    endsAt
    isLive
  }
}

query People($eventId: ID!, $first: Int) {
  people(eventId: $eventId, first: $first) {
    id
    firstName
    lastName
    email
    jobTitle
    organization
    type
  }
}

mutation CreateEvent($input: EventInput!) {
  createEvent(input: $input) {
    id
    title
    slug
  }
}

query MyExhibitors {
  myExhibitors {
    id
    name
    events { id title }
  }
}

query MyLeads($eventId: ID!, $exhibitorId: ID!, $first: Int, $after: String) {
  myLeads(eventId: $eventId, exhibitorId: $exhibitorId, first: $first, after: $after) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id
      connectedAt
      isScanned
      rating
      note
      target {
        ... on Contact { id firstName lastName email organization }
        ... on EventPerson { id firstName lastName email organization }
      }
    }
  }
}

mutation ScanBadges($eventId: ID!, $exhibitorId: ID!, $badges: [BadgeScanInput!]!) {
  scanBadges(eventId: $eventId, exhibitorId: $exhibitorId, badges: $badges) {
    id
    rating
    note
    target {
      ... on Contact { id firstName lastName }
      ... on EventPerson { id firstName lastName }
    }
  }
}
